'use strict';
const atlasKinds={toolkit:'Toolkit',credentials:'Credentials',frameworks:'Frameworks',institutions:'Institutions',law:'Law & privacy',research:'Research'};
let atlasQuery='',atlasGroup='All',coverageQuery='',coverageSource='All',coverageDepth='All';
function atlasPage(kind='toolkit',id){if(!atlasKinds[kind])kind='toolkit';if(id){const item=atlas.find(c=>c.kind===kind&&c.id===id);if(item)return atlasDetail(item);}const groups=[...new Set(atlas.filter(c=>c.kind===kind).flatMap(c=>c.groups))];if(!groups.includes(atlasGroup))atlasGroup='All';return shell(`${heading('THE KNOWLEDGE ATLAS','Find the right reference for the question.','A study-oriented directory extending the learning path across tools, credentials, frameworks, legal sources, institutions, and research. Each entry tells you where it fits and what to investigate next.')}<div class="atlas-nav" aria-label="Reference collections">${Object.entries(atlasKinds).map(([key,label])=>`<a class="atlas-tab ${key===kind?'active':''}" href="#reference/${key}" ${key===kind?'aria-current="page"':''}>${label}<small>${atlas.filter(c=>c.kind===key).length}</small></a>`).join('')}</div>${kind==='credentials'?'<div class="banner"><b>Check status before planning an exam.</b> Source groupings are comparison aids, not universal provider tiers. Retired and closed exams are marked. Compare current objectives, eligibility, maintenance, and cost with the issuer.</div>':kind==='law'?'<div class="banner"><b>Primary sources and current context.</b> Check amendments, commencement, jurisdiction, and the facts of a particular situation. The IPC entry is historical; BNS and DPDP updates are linked. This index does not determine legal applicability.</div>':kind==='toolkit'?'<div class="banner"><b>Learn the workflow before the product.</b> This directory mixes open-source, commercial, and hosted offerings. Licensing, compatibility, and maintenance vary. Use synthetic data and provider labs; reference orientation is not a full tool course.</div>':''}<div class="toolbar"><input type="search" class="search" id="atlas-search" aria-label="Search knowledge atlas" placeholder="Search a tool, role, topic, or reference…" value="${esc(atlasQuery)}"><select id="atlas-group" aria-label="Filter reference category">${['All',...groups].map(g=>`<option ${atlasGroup===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><p class="muted" id="atlas-count" aria-live="polite" style="font-size:11px;margin-bottom:15px"></p><div id="atlas-grid" class="resource-grid" data-kind="${kind}"></div><p class="source-credit">Directory entries are orientations, linked to related lessons and the publisher’s own material. Reference names and links were compared with CyberLab on 2 November 2026. Only specific status updates marked as reviewed were independently checked; other provider pages require your current review. <a href="#coverage">Inspect coverage depth ↗</a></p>`,'reference');}
function atlasCard(c){return `<article class="resource-card" data-tone="${cardTone(c.kind==='toolkit'?c.groups[0]:c.kind)}"><div class="eyebrow">${esc(c.groups[0])} · ${atlasKinds[c.kind]}</div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p>${c.status?`<span class="status-pill ${/Retired|closed|Historical|Legacy/.test(c.status)?'historical':''}">${esc(c.status)}</span>`:''}<div class="resource-actions"><a class="text-link" href="#reference/${c.kind}/${c.id}">Study orientation ↗</a><a class="atlas-publisher" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Publisher ↗</a></div></article>`;}
function updateAtlas(){const grid=$('#atlas-grid');if(!grid)return;const kind=grid.dataset.kind;const result=atlas.filter(c=>c.kind===kind&&(atlasGroup==='All'||c.groups.includes(atlasGroup))&&[c.title,c.desc,c.task,...c.groups,...c.roles].join(' ').toLowerCase().includes(atlasQuery.toLowerCase()));$('#atlas-count').textContent=`${result.length} ${result.length===1?'entry':'entries'} in ${atlasKinds[kind].toLowerCase()} · Reference orientation, with related study`;grid.innerHTML=result.map(atlasCard).join('')||'<div class="empty">No matches. Try a broader search or another category.</div>';}
function atlasDetail(c){const m=modules.find(x=>x.id===c.module);return shell(`<a class="back" href="#reference/${c.kind}">← Back to ${atlasKinds[c.kind].toLowerCase()}</a><article class="article">${heading(atlasKinds[c.kind],esc(c.title),esc(c.desc))}${c.status?`<div class="banner"><b>Status note.</b> ${esc(c.status)}.${c.noteUrl?` <a class="text-link" href="${esc(c.noteUrl)}" target="_blank" rel="noopener noreferrer">Read the update ↗</a>`:''}</div>`:''}<h2>Why this belongs in your toolkit</h2><p>${esc(c.task)}</p><div class="tags">${c.groups.map(g=>`<span class="tag">${esc(g)}</span>`).join('')}</div><h2>A focused study brief</h2><ol><li>Describe the question this ${c.kind==='toolkit'?'tool or platform':'reference'} helps answer. Identify its inputs, outputs, scope, and assumptions.</li><li>Read the publisher’s current material. Record the relevant version, prerequisites, licensing or access conditions, and important limitations.</li><li>Use a synthetic example or an authorized training target. ${c.kind==='law'?'For a legal source, identify the official text, amendments, and commencement without drawing a legal conclusion.':c.kind==='credentials'?'For a credential, compare objectives with your skills and evidence before considering registration.':'Explain what one result would and would not establish.'}</li><li>Write a short note with the evidence, a possible misinterpretation, and the next verification step.</li></ol><div class="concept"><h4>Depth of coverage</h4><p>This entry is an orientation and study brief. The related lesson builds shared understanding; the publisher’s material supplies product-specific or domain-specific detail. Listing an item does not certify proficiency, current availability, or equivalence to a paid course.</p></div><div class="lesson-bottom"><a class="btn" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Read publisher material ↗</a><a class="text-link" href="#lesson/${m.id}/0">Study ${m.title} →</a></div><h2>Your reference notes</h2><textarea class="note-area" data-note="atlas-${c.kind}-${c.id}" aria-label="Reference notes" placeholder="Question, source version, observation, limitation, and next step…">${esc(state.notes[`atlas-${c.kind}-${c.id}`]||'')}</textarea><p class="source-credit">Compared against: ${c.sources.map(esc).join(', ')}. The publisher sets current product, exam, and licensing terms.</p></article>`,'reference');}
function coveragePage(){const depths=[...new Set(coverageRows.map(r=>r.depth))];return shell(`${heading('PUBLIC-REFERENCE COVERAGE AUDIT','Know what is covered—and how.','A transparent map from the Cybersecurity references to NxGenVarsity Unified Platform. Every destination is labeled by its learning depth: a lesson, safe exercise, career orientation, or reference entry. Topic mapping is not proof of mastery or a substitute for the original courses.')}<div class="audit-summary"><div><strong>16 / 16</strong><span>Udemy public sections mapped</span></div><div><strong>8 / 8</strong><span>CyberLab areas indexed</span></div><div><strong>${modules.length} / ${lessonTotal}</strong><span>Modules / original lessons</span></div></div><div class="audit-note"><h3>What this audit can establish</h3><p>The Udemy public outline lists 85 lectures. We inspected its expanded titles and mapped the 16 sections; paid videos, downloads, and assignments were not accessed. CyberLab’s eight areas were inspected, including its tool, role, credential, OSINT, field-lab, standards, legal, and research headings.</p><p>“Concept & defense” covers understanding, evidence, mitigation, and detection. “Safe substitute exercise” replaces remote-control or guessing-tool construction with bounded networking or synthetic decision models. “Reference orientation” is an index and study brief, not a complete lesson on every product.</p><p>Unchecked news statistics, salary estimates, and dated future forecasts are not restated as established current facts. Historical themes and career progression are covered with appropriate context.</p><div class="source-links"><a href="${R.udemy.url}" target="_blank" rel="noopener noreferrer">Inspect Udemy’s public syllabus ↗</a><a href="${R.patil.url}" target="_blank" rel="noopener noreferrer">Inspect CyberLab ↗</a></div></div><div class="toolbar"><input id="coverage-search" class="search" type="search" aria-label="Search coverage topics" placeholder="Find a topic, tool, role, or source area…" value="${esc(coverageQuery)}"><select id="coverage-source" aria-label="Filter coverage source">${['All','Udemy','CyberLab'].map(x=>`<option ${x===coverageSource?'selected':''}>${x}</option>`).join('')}</select><select id="coverage-depth" aria-label="Filter coverage depth">${['All',...depths].map(x=>`<option ${x===coverageDepth?'selected':''}>${x}</option>`).join('')}</select></div><p id="coverage-count" aria-live="polite" class="muted" style="font-size:11px;margin-bottom:14px"></p><div class="coverage-wrap"><table class="coverage-table"><caption class="screen-reader">Reference topic, previous coverage, current depth, and study destination</caption><thead><tr><th scope="col">Reference & topic</th><th scope="col">Version 1</th><th scope="col">Current depth</th><th scope="col">Where to study</th></tr></thead><tbody id="coverage-body"></tbody></table></div><p class="source-credit">Review date: 2 November 2026. “Gap” and “Partial” describe the original version’s coverage. “Mapped” means a destination exists at the stated depth, not that every paid-course skill has an equivalent lab. Original provider material remains independently owned.</p>`,'reference');}
function coverageLinkLabel(url,label){if(url.startsWith('#lesson/')){const [,id,index]=url.slice(1).split('/');const m=modules.find(x=>x.id===id);return m?.lessons[Number(index)]?.title||label;}return label;}
function updateCoverage(){const result=coverageRows.filter(r=>(coverageSource==='All'||r.source===coverageSource)&&(coverageDepth==='All'||r.depth===coverageDepth)&&[r.source,r.area,r.topic,r.depth].join(' ').toLowerCase().includes(coverageQuery.toLowerCase()));$('#coverage-count').textContent=`${result.length} mapped rows · ${new Set(result.map(r=>r.source+':'+r.area)).size} source area${new Set(result.map(r=>r.source+':'+r.area)).size===1?'':'s'} · Filter by depth to distinguish lessons from references`;$('#coverage-body').innerHTML=result.map(r=>`<tr><td><small>${r.source} · ${esc(r.area)}${r.section?' · Section '+r.section+' · Lectures '+r.lectures:''}</small><b>${esc(r.topic)}</b></td><td><span class="old-coverage">${r.before}</span></td><td><span class="depth-label ${r.depth.includes('Concept')||r.depth.includes('substitute')?'concept-depth':''}">${r.depth}</span></td><td>${r.links.map(([url,label])=>`<a href="${url}">${esc(coverageLinkLabel(url,label))} →</a>`).join('')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No matching topics. Try another source or a broader search.</td></tr>';}
function fieldPage(view){if(view==='glossary')return shell(`<a class="back" href="#field">← Back to field guide</a>${heading('THE SHARED VOCABULARY','Understand the terms. Explain the idea.','A concise glossary for reading lessons, advisories, and job descriptions. Terms are starting points; follow the related original sources for precise definitions.')}<div class="glossary-grid">${glossary.map(([term,desc])=>`<article class="resource-card"><h3>${term}</h3><p>${desc}</p></article>`).join('')}</div>`,'labs');if(view==='terminal')return terminalPage();if(view==='scan')return scanPage();if(view==='throttle')return throttlePage();return shell(`${heading('THE FIELD GUIDE','Build skills in a sensible order.','A practical companion to the learning path: lab preparation, ten focused challenges, a small simulated terminal, and clear evidence to keep from each exercise.')}<div class="flow-diagram"><div><strong>01</strong>Foundations</div><span>→</span><div><strong>02</strong>Technical depth</div><span>→</span><div><strong>03</strong>Scoped assessment</div><span>→</span><div><strong>04</strong>Professional evidence</div></div><div class="banner"><b>Readiness, not tool count.</b> Be able to explain operating systems, networking, shell navigation, Windows, Python, HTTP, discovery, scanning, web risks, and reporting. Use the full roadmap to revisit any foundation.</div><div class="field-links"><a href="#field/terminal">Simulated terminal →</a><a href="#field/scan">Synthetic scan →</a><a href="#field/throttle">Throttle model →</a><a href="#field/glossary">Glossary →</a><a href="#roadmap">Full roadmap →</a></div><div class="section-top"><div><h2>Ten beginner challenges</h2><p>Keep the evidence small, reproducible, and safe to share.</p></div></div><div class="timeline">${challenges.map((c,i)=>`<article class="timeline-item"><div class="timeline-num">${String(i+1).padStart(2,'0')}</div><div><h3>${c.title}</h3><p>${c.task}</p><p style="margin-top:9px"><b>Evidence to keep:</b> ${c.evidence}</p><div class="field-actions"><a class="text-link" href="${c.action||'#lesson/'+c.module+'/0'}">${c.action?'Open exercise':'Study the foundation'} →</a><label class="challenge-done"><input type="checkbox" data-challenge="${i}" ${state.challenges?.[i]?'checked':''}> Mark attempted</label></div></div></article>`).join('')}</div><div class="audit-note"><h3>Common pitfalls to avoid</h3><p>Installing Kali without understanding the system; memorizing commands without understanding their effects; letting tools replace hypotheses; copying unreviewed exploits; skipping network fundamentals; neglecting reporting; and attempting too many specializations at once.</p><p>A stronger habit is to explain the objective, predict an observation, run a bounded exercise, compare the result, and write what you would improve.</p></div>`,'labs');}
let terminalPath='/lab',terminalHistory=['NxGenVarsity training terminal · simulation only','Type help to see the supported commands. No commands run on your computer.'];
const terminalFiles={'/lab/README.txt':'AUTHORIZED TRAINING ONLY\nThis virtual workspace contains synthetic data. No network access, command execution, or real secrets. Read notes/scope.txt next.','/lab/notes/scope.txt':'Scope: the synthetic files in /lab.\nGoal: read the sample log and explain a finding.\nStop condition: any request for real credentials or a real target.','/lab/events.log':'09:41 alex SIGN_IN_FAILED\n09:42 alex SIGN_IN_SUCCESS\nThis small sample is insufficient to confirm compromise.'};
function terminalPage(){return shell(`<a class="back" href="#field">← Back to field guide</a>${heading('BROWSER SIMULATION · NO SYSTEM ACCESS','Learn the shape of a shell.','Practice a few read-only commands against a tiny synthetic filesystem. This is not a real terminal and does not provide a Linux execution environment.')}<div class="training-terminal"><pre id="terminal-output" role="log" aria-live="polite">${esc(terminalHistory.join('\n'))}</pre><form id="terminal-form"><label for="terminal-command" id="terminal-prompt">student:${terminalPath}$</label><input id="terminal-command" autocomplete="off" spellcheck="false" aria-label="Simulated terminal command" placeholder="Try help"></form></div><div class="banner"><b>Your mission.</b> Read README.txt, move into notes, read scope.txt, return to /lab, then inspect events.log. Explain why the sample cannot confirm a compromise.</div><button class="btn outline" id="terminal-reset">Reset the simulation ↻</button>`,'labs');}
function resolveTerminalPath(name){if(!name)return terminalPath;const parts=(name.startsWith('/')?name:terminalPath+'/'+name).split('/'),out=[];for(const v of parts){if(v==='..')out.pop();else if(v&&v!=='.')out.push(v);}return '/'+out.join('/');}
function runTerminal(command){const clean=command.trim();if(!clean)return;terminalHistory.push(`student:${terminalPath}$ ${clean}`);const [cmd,...args]=clean.split(/\s+/);let out='';if(/[;&|`<>$]/.test(clean))out='Only the documented simulated commands are supported. No shell operators or execution.';else if(cmd==='help')out='help · pwd · whoami · ls [path] · cd [path] · cat <file> · clear\nFiles are synthetic. There is no network, package manager, or operating-system shell.';else if(cmd==='pwd')out=terminalPath;else if(cmd==='whoami')out='student (simulation)';else if(cmd==='ls'){const dir=resolveTerminalPath(args[0]);if(['/lab','/lab/notes'].includes(dir))out=dir==='/lab'?'README.txt  events.log  notes/':'scope.txt';else out='No such simulated directory.';}else if(cmd==='cd'){const dir=resolveTerminalPath(args[0]||'/lab');if(['/lab','/lab/notes'].includes(dir))terminalPath=dir;else out='Only /lab and /lab/notes exist in this simulation.';}else if(cmd==='cat')out=terminalFiles[resolveTerminalPath(args[0])]||'No such synthetic file. Try ls.';else if(cmd==='clear')terminalHistory=[];else out='Unsupported simulated command. Type help. No command was executed.';if(out)terminalHistory.push(out);$('#terminal-output').textContent=terminalHistory.join('\n');$('#terminal-prompt').textContent=`student:${terminalPath}$`;$('#terminal-command').value='';}
function scanPage(){return shell(`<a class="back" href="#field">← Back to field guide</a><article class="article">${heading('SYNTHETIC OUTPUT · NO SCANNER RUNS','What does the scan actually tell you?','Read this fictional inventory observation before choosing a validation step. The example uses a documentation address.')}<div class="log-block">Target: 192.0.2.30 (synthetic)\nVantage: learner network\nPORT     STATE     OBSERVED SERVICE\n22/tcp   open      SSH banner\n80/tcp   closed    connection refused\n443/tcp  filtered  no conclusive reply\n\nInventory owner reports an HTTPS service behind a policy boundary.</div><h2>Choose a next step</h2><div class="answers"><button class="answer" data-scan="0">A. Declare HTTPS absent because no reply was conclusive.</button><button class="answer" data-scan="1">B. Confirm approved connectivity and service configuration, compare evidence from the correct vantage, then validate applicability.</button><button class="answer" data-scan="2">C. Treat an SSH banner as proof of a critical vulnerability.</button></div><div class="feedback" id="scan-feedback" role="status"></div><div class="concept"><h4>Why this matters</h4><p>A scan is an observation under particular network conditions. A filtered result and a product banner do not establish application absence or vulnerability.</p></div><a class="text-link" href="#lesson/assessment/0">Review scan interpretation →</a></article>`,'labs');}
function throttlePage(){return shell(`<a class="back" href="#field">← Back to field guide</a><article class="article">${heading('LOCAL TOY MODEL · NO AUTHENTICATION REQUESTS','Explore a rate-limit tradeoff.','A fixed set of synthetic attempts passes through a simple rolling-window rule. The model counts allowed attempts in the preceding 60 seconds, including the current attempt; it is not an authentication system.')}<label class="note-label" for="throttle-limit">Allowed attempts per 60-second window</label><select id="throttle-limit"><option value="2">2 attempts</option><option value="3" selected>3 attempts</option><option value="5">5 attempts</option></select><div id="throttle-results" class="log-block" role="status"></div><h2>Reason about the limits</h2><p>The attempts occur at seconds 0, 10, 20, 30, 40, 70, and 80. An event exactly 60 seconds after an earlier allowed event falls outside that earlier event’s window in this model. Throttled attempts do not extend the cooldown.</p><p>This ignores identity verification, passwords, distributed behavior, recovery, and legitimate shared networks. Compare false blocks and missed abuse before proposing a real control. A lower threshold alone is not automatically a better policy.</p><textarea class="note-area" data-note="throttle" aria-label="Throttle model notes" placeholder="What changed? Which legitimate behavior could be blocked? What does the model omit?">${esc(state.notes.throttle||'')}</textarea><a class="text-link" href="#lesson/credentialaudit/1">Build the Python simulation brief →</a></article>`,'labs');}
function throttleDecisions(limit){const allowed=[];return [0,10,20,30,40,70,80].map(t=>{const n=allowed.filter(a=>t-a<60).length;const pass=n<limit;if(pass)allowed.push(t);return {time:t,decision:pass?'ALLOW':'THROTTLE'};});}
function updateThrottle(){const el=$('#throttle-results');if(el)el.textContent=throttleDecisions(Number($('#throttle-limit').value)).map(r=>`${String(r.time).padStart(2,'0')}s  ${r.decision}`).join('\n');}
document.addEventListener('input',e=>{if(e.target.id==='atlas-search'){atlasQuery=e.target.value;updateAtlas();}if(e.target.id==='coverage-search'){coverageQuery=e.target.value;updateCoverage();}});
document.addEventListener('change',e=>{if(e.target.id==='atlas-group'){atlasGroup=e.target.value;updateAtlas();}if(e.target.id==='coverage-source'){coverageSource=e.target.value;updateCoverage();}if(e.target.id==='coverage-depth'){coverageDepth=e.target.value;updateCoverage();}if(e.target.id==='throttle-limit')updateThrottle();if(e.target.dataset.challenge!==undefined){state.challenges??={};state.challenges[e.target.dataset.challenge]=e.target.checked;persist();}});
document.addEventListener('submit',e=>{if(e.target.id==='terminal-form'){e.preventDefault();runTerminal($('#terminal-command').value);}});
document.addEventListener('click',e=>{if(e.target.closest('#terminal-reset')){terminalPath='/lab';terminalHistory=['Simulation reset. Type help to begin.'];$('#terminal-output').textContent=terminalHistory.join('\n');$('#terminal-prompt').textContent='student:/lab$';$('#terminal-command').value='';}const s=e.target.closest('[data-scan]');if(s){s.closest('.answers').querySelectorAll('button').forEach(b=>b.classList.remove('correct','incorrect'));const good=s.dataset.scan==='1';s.classList.add(good?'correct':'incorrect');$('#scan-feedback').textContent=good?'✓ Correct. Validate scope, network vantage, and configuration before making a finding.':'That conclusion goes beyond the evidence. A banner or filtered observation needs contextual verification.';}});
const toolkitRoleGroups={soc:'SOC Analyst',detection:'SOC Analyst',pentest:'Penetration Tester / Red Team',redlead:'Penetration Tester / Red Team',dfir:'Forensics & Malware Analyst',forensicinvestigator:'Forensics & Malware Analyst',malwareanalyst:'Forensics & Malware Analyst',appsec:'AppSec / DevSecOps Engineer',devsecops:'AppSec / DevSecOps Engineer',cloud:'Cloud Security Engineer',cloudsupport:'Cloud Security Engineer',cloudarchitect:'Cloud Security Engineer',cloudlead:'Cloud Security Engineer',iam:'IAM Engineer',support:'IAM Engineer',grc:'GRC / Compliance Analyst',risklead:'GRC / Compliance Analyst',ml:'ML / AI Engineer',mlentry:'ML / AI Engineer',mlsenior:'ML / AI Engineer',ailead:'ML / AI Engineer',architect:'CISO / Leadership',ciso:'CISO / Leadership',director:'CISO / Leadership'};
document.addEventListener('click',e=>{const a=e.target.closest('[data-role-toolkit]');if(a){atlasQuery='';atlasGroup=toolkitRoleGroups[a.dataset.roleToolkit]||'All';}});
document.addEventListener('input',e=>{if(e.target.id==='career-search'){const q=e.target.value.toLowerCase();let n=0;document.querySelectorAll('.career-grid .career').forEach(c=>{const show=c.textContent.toLowerCase().includes(q);c.hidden=!show;if(show)n++;});$('#career-count').textContent=`${n} career orientations shown`;}});
